def saturation(T_C: float) -> dict:
    """Saturated water at T_C (1-220 C): P (MPa), h_f, h_g (kJ/kg), v_f (m3/kg)."""
    if not (_T[0] <= T_C <= _T[-1]):
        raise ValueError(f"water saturation table covers {_T[0]}-{_T[-1]} C, not {T_C} C")
    i = min(max(bisect.bisect_right(_T, T_C) - 1, 0), len(_T) - 2)
    a, b = SATURATION[i], SATURATION[i + 1]
    t = (T_C - a[0]) / (b[0] - a[0])
    P, hf, hg, vf = (a[k] + t * (b[k] - a[k]) for k in range(1, 5))
    return dict(P=P, h_f=hf, h_g=hg, v_f=vf)


def feedwater_enthalpy(T_feed: float, P_MPa: float) -> float:
    """Liquid water at T_feed pumped to P_MPa (kJ/kg): h_f plus the v dP pump work."""
    s = saturation(T_feed)
    return s["h_f"] + s["v_f"] * (P_MPa - s["P"]) * 1000.0


def steam_from_feedwater(Q_kW: float, T_steam: float, T_feed: float) -> dict:
    """Saturated steam at T_steam raised from feedwater at T_feed with duty Q_kW."""
    if T_feed >= T_steam:
        raise ValueError(f"feedwater at {T_feed:g} C is not below the steam temperature {T_steam:g} C")
    s = saturation(T_steam)
    h_feed = feedwater_enthalpy(T_feed, s["P"])
    dh = s["h_g"] - h_feed
    # preheat_kJkg: feedwater to saturated liquid (the sensible part, before evaporation)
    return dict(m_kgs=Q_kW / dh, dh_kJkg=dh, h_feed_kJkg=h_feed, h_steam_kJkg=s["h_g"], P_steam_MPa=s["P"],
                preheat_kJkg=s["h_f"] - h_feed)
